    fun measure(text: String, scale: Float): Float =
        text.sumOf { (glyphs[it]?.advance ?: 0f).toDouble() }.toFloat()*scale*7f

    fun draw(out: MutableList<JunctionScene.Shape>, text: String, x: Float, y: Float,
             scale: Float, color: Long, background: Long = 0xFF071C30L) {
        val height=scale*7f
        var cursor=x
        for (c in text) {
            val glyph=glyphs[c] ?: continue
            for (contour in glyph.contours) out += JunctionScene.Shape.Fill(
                contour.points.map { JunctionScene.P(cursor+it.x*height,y+it.y*height) },
                if(contour.foreground) color else background)
            cursor+=glyph.advance*height
        }
    }
}
